async function runPool<T>(tasks: (() => Promise<T>)[], limit: number) {
  const results: T[] = []
  for (let i = 0; i < tasks.length; i += limit) {
    const batch = tasks.slice(i, i + limit).map((t) => t())
    results.push(...(await Promise.all(batch)))
  }
  return results
}

